package com.bank.batch;

import java.util.OptionalInt;
import java.util.logging.Logger;

// Parses batch fields safely, decodes radix-encoded fields, and renders flags.
class BatchFieldParser {
    private static final Logger log = Logger.getLogger(BatchFieldParser.class.getName());

    // Base-10 parse that handles bad input WITHOUT crashing the batch.
    OptionalInt parseCount(String raw) {
        if (raw == null) return OptionalInt.empty();
        String trimmed = raw.trim();
        try {
            return OptionalInt.of(Integer.parseInt(trimmed));
        } catch (NumberFormatException e) {
            // log and route for investigation — do NOT silently default
            log.warning(() -> "Invalid count field '" + raw + "': " + e.getMessage());
            return OptionalInt.empty();
        }
    }

    // Decode a hexadecimal reference code (radix 16).
    int parseHexReference(String hex) {
        return Integer.parseInt(hex, 16); // "FF" -> 255
    }

    // Decode a binary feature-flag field (radix 2).
    int parseBinaryFlags(String bits) {
        return Integer.parseInt(bits, 2); // "1010" -> 10
    }

    // Render a status int as hex and binary strings for output/protocol.
    String toHex(int value) { return Integer.toHexString(value); }
    String toBinary(int value) { return Integer.toBinaryString(value); }
    String toRadix(int value, int radix) { return Integer.toString(value, radix); }
}
