package com.bank.batch;

import java.util.OptionalInt;
import java.util.logging.*;

public class RadixParseDemo {
    private static final Logger log = Logger.getLogger(RadixParseDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BatchFieldParser parser = new BatchFieldParser();

        // 1) Valid base-10 count.
        OptionalInt good = parser.parseCount("  42 ");
        log.info(() -> "parseCount('  42 ') -> " + good);

        // 2) Invalid base-10 input -> NumberFormatException handled gracefully.
        OptionalInt bad = parser.parseCount("abc");
        log.info(() -> "parseCount('abc') -> " + bad + " (bad record routed, batch continues)");

        // 3) Direct demonstration of the exception for the classic case.
        try {
            int n = Integer.parseInt("abc");
            log.info(() -> "unexpected " + n);
        } catch (NumberFormatException e) {
            log.warning(() -> "Integer.parseInt(\"abc\") threw NumberFormatException: " + e.getMessage());
        }

        // 4) Radix parsing: hex and binary.
        int ref = parser.parseHexReference("FF");
        int flags = parser.parseBinaryFlags("1010");
        log.info(() -> "parseInt('FF',16) -> " + ref);
        log.info(() -> "parseInt('1010',2) -> " + flags);

        // 5) Rendering an int into hex, binary, and an arbitrary radix.
        int status = 255;
        log.info(() -> "toHexString(255) -> " + parser.toHex(status));
        log.info(() -> "toBinaryString(255) -> " + parser.toBinary(status));
        log.info(() -> "toString(255, 36) -> " + parser.toRadix(status, 36));

        // 6) Invalid digit for the radix also throws.
        try {
            int oops = Integer.parseInt("2", 2); // '2' is not a binary digit
            log.info(() -> "unexpected " + oops);
        } catch (NumberFormatException e) {
            log.warning(() -> "parseInt('2',2) threw: invalid binary digit");
        }
    }
}

